const config = $node['Load System Config'].json.data?.attributes || $node['Load System Config'].json.data || {};
const brand = $node['Load Brand DNA'].json.data?.attributes || $node['Load Brand DNA'].json.data || {};
const learningsRaw = $node['Load AI Learnings'].json?.data;
const learnings = (Array.isArray(learningsRaw) && learningsRaw.length > 0) ? (learningsRaw[0].attributes || learningsRaw[0]).learnings_json || {} : {};
const req = $node['Webhook POST /generate-content'].json.body || {};

const dishName = req.dish_name || req.product_name || 'plat signature';
const brandName = brand.restaurant_name || brand.name || 'Ralphé';
const brandStyle = brand.brand_style || 'modern algérien, chaleureux, street food haut de gamme';
const brandColors = brand.brand_colors || 'rouge, or, noir';
const bestChannel = learnings.best_channel || 'instagram';
const peakHours = learnings.peak_hours || [12, 19, 20];

// Platform-specific aspect ratios
const formats = {
  reels_tiktok: { ratio: '9:16', width: 1080, height: 1920, platforms: ['instagram_reel', 'tiktok', 'whatsapp_status'] },
  feed_square: { ratio: '1:1', width: 1080, height: 1080, platforms: ['instagram_feed', 'facebook_post'] },
  fb_landscape: { ratio: '16:9', width: 1920, height: 1080, platforms: ['facebook_cover', 'web_banner'] }
};

// Build prompts with brand DNA
const imagePrompt = `Professional food photography of ${dishName} from ${brandName}. Style: ${brandStyle}. Colors: ${brandColors}. Shot on 85mm lens, shallow depth of field, warm golden hour lighting, steam rising, garnished beautifully. Restaurant ambiance in background. Hero shot, menu-worthy, Instagram-viral quality. NO text, NO watermarks.`;

const videoPrompt = `Cinematic 5-second food video of ${dishName} at ${brandName}. Slow motion reveal, steam rising, cheese pull or sauce drizzle. Style: ${brandStyle}. Professional restaurant lighting, shallow DOF, mouth-watering close-up. Vertical 9:16 format for Reels/TikTok.`;

return [{ json: {
  dish_name: dishName,
  brand_name: brandName,
  brand_style: brandStyle,
  image_prompt: imagePrompt,
  video_prompt: videoPrompt,
  formats,
  best_channel: bestChannel,
  peak_hours: peakHours,
  config,
  retry_count: 0,
  max_retries: 2
}}];

const brief = $node['Build Creative Brief'].json;
const imgSquare = $node['Gen Image 1:1 (Feed)'].json;
const imgVertical = $node['Gen Image 9:16 (Stories/Reels)'].json;
const video = $node['Gen Video 9:16 (Reels/TikTok)'].json;
const captionRaw = $node['Gen A/B Captions (LLM)'].json;

// Parse captions
let captions = { caption_a: '', caption_b: '', hashtags: [] };
try {
  const content = captionRaw.message?.content || captionRaw.response || '{}';
  const jsonMatch = content.match(/```json?\s*([\s\S]*?)```/) || [null, content];
  captions = JSON.parse(jsonMatch[1].trim());
} catch(e) {
  captions = {
    caption_a: `🔥 ${brief.dish_name} chez ${brief.brand_name}! Commandez maintenant 📲`,
    caption_b: `Vous connaissez cette sensation quand ${brief.dish_name} arrive devant vous? 🤤 Chez ${brief.brand_name}, c'est tous les jours comme ça. Fi dar wella livraison, à vous de choisir! 📲`,
    hashtags: ['#fooddz', '#algeriafood', '#resto', '#livraison', `#${brief.brand_name.replace(/\s/g,'').toLowerCase()}`]
  };
}

return [{ json: {
  dish_name: brief.dish_name,
  brand_name: brief.brand_name,
  image_square_url: imgSquare.images?.[0] ? `data:image/png;base64,${imgSquare.images[0]}` : (imgSquare.output || imgSquare.urls?.get || null),
  image_vertical_url: imgVertical.images?.[0] ? `data:image/png;base64,${imgVertical.images[0]}` : (imgVertical.output || imgVertical.urls?.get || null),
  video_url: video.output || video.urls?.get || null,
  caption_a: captions.caption_a || '',
  caption_b: captions.caption_b || '',
  hashtags: captions.hashtags || [],
  config: brief.config,
  best_channel: brief.best_channel,
  peak_hours: brief.peak_hours,
  retry_count: brief.retry_count
}}];

