const pkg = $node['Assemble Content Package'].json;
const scoreRaw = $json.message?.content || $json.response || '{}';
let score = 7;
let reasoning = '';
let improvements = [];
try {
  const jsonMatch = scoreRaw.match(/```json?\s*([\s\S]*?)```/) || [null, scoreRaw];
  const parsed = JSON.parse(jsonMatch[1].trim());
  score = parsed.score || 7;
  reasoning = parsed.reasoning || '';
  improvements = parsed.improvements || [];
} catch(e) {
  // If image + video + caption all exist, default score 7
  score = (pkg.image_square_url && pkg.caption_a) ? 7 : 4;
}

const passesQA = score >= 7;
const canRetry = pkg.retry_count < 2;

return [{ json: {
  ...pkg,
  quality_score: score,
  quality_reasoning: reasoning,
  quality_improvements: improvements,
  passes_qa: passesQA,
  should_retry: !passesQA && canRetry,
  status: passesQA ? 'ready' : (canRetry ? 'retry' : 'failed')
}}];
